#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<int,int> pii;

const int INF = 1e9;
const int MAXN = 15;
const int MAXT = 65;

char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int dist[MAXN][MAXN];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int node_id[MAXT][MAXN][MAXN];
int id_counter = 1;

struct Edge {
    int u, v;
    LL cap, flow;
    Edge() {}
    Edge(int u, int v, LL cap) : u(u), v(v), cap(cap), flow(0) {}
};

struct Dinic {
    int N;
    vector<Edge> E;
    vector<vector<int>> g;
    vector<int> d, pt;

    Dinic(int N) : N(N), E(), g(N), d(N), pt(N) {}

    void add_edge(int u, int v, LL cap) {
        if (u == v) return;
        E.emplace_back(u, v, cap);
        g[u].push_back((int)E.size()-1);
        E.emplace_back(v, u, 0);
        g[v].push_back((int)E.size()-1);
    }

    bool bfs(int S, int T) {
        fill(d.begin(), d.end(), N+1);
        d[S] = 0;
        queue<int> q;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == T) break;
            for (int idx : g[u]) {
                Edge &e = E[idx];
                if (e.flow < e.cap && d[e.v] > d[e.u] + 1) {
                    d[e.v] = d[e.u] + 1;
                    q.push(e.v);
                }
            }
        }
        return d[T] != N+1;
    }

    LL dfs(int u, int T, LL flow = -1) {
        if (u == T || flow == 0) return flow;
        for (int &i = pt[u]; i < (int)g[u].size(); ++i) {
            Edge &e = E[g[u][i]];
            Edge &oe = E[g[u][i]^1];
            if (d[e.v] == d[e.u] + 1) {
                LL amt = e.cap - e.flow;
                if (flow != -1 && amt > flow) amt = flow;
                LL pushed = dfs(e.v, T, amt);
                if (pushed) {
                    e.flow += pushed;
                    oe.flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    LL max_flow(int S, int T) {
        LL total = 0;
        while (bfs(S, T)) {
            fill(pt.begin(), pt.end(), 0);
            while (LL flow = dfs(S, T))
                total += flow;
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    memset(dist, -1, sizeof(dist));
    int n, t;
    cin >> n >> t;
    for (int i = 1; i <= n; ++i) {
        cin >> (grid1[i] + 1);
    }

    // assign node ids
    for (int time = 0; time <= t+1; ++time) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                node_id[time][i][j] = id_counter++;
            }
        }
    }
    int source = 0, sink = id_counter;
    id_counter++;

    for (int i = 1; i <= n; ++i) {
        cin >> (grid2[i] + 1);
    }

    // BFS from all 'Z' cells
    queue<pii> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                q.emplace(i, j);
                dist[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        auto [uy, ux] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int vy = uy + dir[d][0], vx = ux + dir[d][1];
            if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && grid1[vy][vx] != 'Y' && dist[vy][vx] == -1) {
                dist[vy][vx] = dist[uy][ux] + 1;
                q.emplace(vy, vx);
            }
        }
    }

    // cap distances
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (dist[i][j] == -1 || dist[i][j] > t) dist[i][j] = INF;
        }
    }

    Dinic dinic(id_counter);
    // source edges
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                dinic.add_edge(source, node_id[0][i][j], grid1[i][j] - '0');
            }
        }
    }

    // time edges
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int vy = i + dir[d][0], vx = j + dir[d][1];
                if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && grid1[vy][vx] != 'Y' && grid1[vy][vx] != 'Z') {
                    for (int x = 0; x < t; ++x) {
                        if (dist[vy][vx] >= x+1 && dist[i][j] > x) {
                            dinic.add_edge(node_id[x][i][j], node_id[x+1][vy][vx], 1000);
                        }
                    }
                }
            }
        }
    }

    // sink edges (two steps combined)
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Y' || grid1[i][j] == 'Z') continue;
            if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                int cap = grid2[i][j] - '0';
                for (int x = 0; x <= t; ++x) {
                    dinic.add_edge(node_id[x][i][j], node_id[t+1][i][j], cap);
                }
                dinic.add_edge(node_id[t+1][i][j], sink, cap);
            }
        }
    }

    cout << dinic.max_flow(source, sink) << '\n';
    return 0;
}
